import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const voidSwordCard='a2-p09-r2c1';
export const voidSwordAdvances=['a2-p24-r1c3','a2-p24-r2c1','a2-p24-r2c3','a2-p24-r3c1'] as const;
export const voidSwordScenarios=['void-sword-ordinary','void-sword-guard','void-sword-owner-ordinary','void-sword-low','void-sword-dedicated','void-sword-pair','void-sword-all','void-sword-cost-one','void-sword-cost-two','void-sword-cost-four','void-sword-near','void-sword-same-faction','void-sword-water-ordinary','void-sword-water-zero','void-sword-water-one','void-sword-water-two','void-sword-maai','void-sword-maai-spare','void-sword-evade-ordinary','void-sword-evade-dedicated','void-sword-fate','void-sword-suppressed','void-sword-silenced','void-sword-stopped','void-sword-wrong-owner','void-sword-decline','void-sword-noncounter','void-sword-invalid-cost'] as const;
export type VoidSwordScenario=typeof voidSwordScenarios[number];
export function isVoidSwordScenario(name:string):name is VoidSwordScenario{return (voidSwordScenarios as readonly string[]).includes(name);}
export function voidSwordMode(name:VoidSwordScenario){const suffix=name.replace('void-sword-',''),dedicated=!['ordinary','guard','owner-ordinary','low','evade-ordinary','water-ordinary','decline'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',guard=!['ordinary','low','decline'].includes(suffix),water=suffix.startsWith('water-'),costCount=({'cost-one':1,'cost-two':2,'cost-four':4,'water-one':1,'water-two':2,maai:1,'maai-spare':1,fate:2,suppressed:2,silenced:2,'invalid-cost':2} as Record<string,number>)[suffix]??0,costs=voidSwordAdvances.slice(0,costCount),targets=['all','cost-four'].includes(suffix)?[1,2,3]:suffix==='same-faction'?[1,3]:['pair','cost-one','cost-two','maai','maai-spare','fate','suppressed','silenced'].includes(suffix)?[1,2]:[1];return {suffix,dedicated,owner,guard,water,costs,targets};}
export function makeVoidSwordPhysical(name:VoidSwordScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=voidSwordMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'黒騎士ガーウィン':'侍大将のシン',m.owner?'侍大将のシン':'獣使いのウパニシャット','黒妖精のアーネス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?5:m.dedicated?0:6))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,voidSwordCard),takeCard(s,d,'a2-p02-r2c3')];for(const id of m.costs)keep.push(takeCard(s,a,id));if(m.guard)keep.push(takeCard(s,b,m.water?'a2-p23-r1c1':'a2-p22-r3c3'),takeCard(s,c,'a2-p18-r3c3'));
 if(m.suffix==='near')keep.push(takeCard(s,a,voidSwordAdvances[0]));if(m.suffix==='maai-spare')keep.push(takeCard(s,a,voidSwordAdvances[1]));if(m.suffix.startsWith('maai'))keep.push(takeCard(s,b,'a2-p06-r1c3'));if(m.suffix.startsWith('evade'))keep.push(takeCard(s,b,'a2-p05-r3c1'));if(m.suffix==='invalid-cost')keep.push(takeCard(s,a,'a2-p06-r1c3'),takeCard(s,a,'a2-p08-r3c3'),takeCard(s,b,voidSwordAdvances[2]));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`VOID_SWORD_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('VOID_SWORD_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('VOID_SWORD_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('VOID_SWORD_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.guard&&(id===b||id===c))act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:id===b?m.water?'a2-p23-r1c1':'a2-p22-r3c3':'a2-p18-r3c3'});act(id,{type:'PASS_SETUP'});}if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('VOID_SWORD_FIXTURE_COUNTER_LIMIT');}
 if(m.suffix==='near'){act(a,{type:'APPROACH',cardInstanceId:voidSwordAdvances[0],targetId:b});settle();}if(m.suffix==='same-faction'){act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
